import type { ApproveToolCall } from '@lousho/build-ai-agent';

/**
 * The kit's approver (pointed at by `agent.json`'s `approve`): what reaches
 * this function is the 'ask' tier of the permission rules - production
 * remediation and anything the rules did not list.
 *
 *   tier 2 - reversible production remediation (restart, bounded scale):
 *            auto-approved, and the approval is annotated with its tier so the
 *            decision record carries why it was allowed through.
 *   tier 3 - anything hotter (scaling a service to zero, tools outside the
 *            remediation set): refused, so the call escalates to a human
 *            instead of running on the agent's own authority.
 */
const TIER_2 = new Set(['restart_service', 'scale_replicas']);

const approve: ApproveToolCall = ({ toolName, args }) => {
  const environment = String(args.environment ?? 'production');
  if (toolName === 'scale_replicas' && Number(args.replicas) === 0) {
    return false; // scaling to zero is an outage, not a remediation - tier 3
  }
  if (!TIER_2.has(toolName)) {
    return false; // outside the remediation set - tier 3, a human decides
  }
  return `approved at risk tier 2: '${toolName}' on ${environment} is reversible - verify within the incident window`;
};

export default approve;

import { webhookChannel } from '@lousho/build-ai-agent';

/**
 * Alert intake (PagerDuty-style): POSTs land on /channels/alerts; the JSON
 * body's `input` string - or the whole body - becomes the alert the agent
 * works on, and a `sessionKey` keeps one incident in one session.
 *
 * With INCIDENT_WEBHOOK_SECRET set, requests must carry a GitHub-style
 * 'x-signature-256: sha256=<hmac of the raw body>' header. Without it the
 * channel accepts unauthenticated requests - local development only; always
 * set the secret in a deployment.
 */
export default webhookChannel({
  name: 'alerts',
  ...(process.env.INCIDENT_WEBHOOK_SECRET ? { secret: process.env.INCIDENT_WEBHOOK_SECRET } : {}),
});

import { appendFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';
import type { AgentHook } from '@lousho/build-ai-agent';

/**
 * The kit's hooks (pointed at by `agent.json`'s `hooks`): the incident audit
 * trail. Every tool call and its outcome is appended to `timeline` (in-memory,
 * readable by anything that shares this module) and - when
 * `INCIDENT_TIMELINE_FILE` is set - to that file as JSON lines, so a deploy
 * keeps a durable record of what the agent did during an incident.
 */

export interface TimelineEntry {
  at: string;
  /** 'call' = invoked; 'approval' = paused for a human; 'result' / 'error' = settled. An approved call re-enters the pipeline, so it records 'call' twice. */
  phase: 'call' | 'approval' | 'result' | 'error';
  toolName: string;
  toolCallId: string;
  sessionId?: string;
  args?: Record<string, unknown>;
  detail?: string;
}

/** Every tool call the agent has made, in order - the in-memory incident timeline. */
export const timeline: TimelineEntry[] = [];

/** Clear the in-memory timeline (tests). */
export function resetTimeline(): void {
  timeline.length = 0;
}

function summarize(result: unknown, error?: string): string | undefined {
  if (error !== undefined) return `error: ${error}`;
  const text = typeof result === 'string' ? result : JSON.stringify(result ?? null);
  return text.length > 300 ? `${text.slice(0, 300)}…` : text;
}

function record(entry: TimelineEntry): void {
  timeline.push(entry);
  const file = process.env.INCIDENT_TIMELINE_FILE;
  if (file === undefined || file === '') return;
  mkdirSync(path.dirname(file), { recursive: true });
  appendFileSync(file, `${JSON.stringify(entry)}\n`, 'utf8');
}

/** Append each tool call and its outcome to the incident timeline. */
export function incidentTimeline(): AgentHook {
  return {
    name: 'incident-timeline',
    preToolCall(ctx) {
      record({ at: new Date().toISOString(), phase: 'call', toolName: ctx.toolName, toolCallId: ctx.toolCallId, ...(ctx.sessionId && { sessionId: ctx.sessionId }), args: { ...ctx.args } });
    },
    postToolCall(ctx, result) {
      record({
        at: new Date().toISOString(),
        phase: result.requiresApproval ? 'approval' : result.error ? 'error' : 'result',
        toolName: ctx.toolName,
        toolCallId: ctx.toolCallId,
        ...(ctx.sessionId && { sessionId: ctx.sessionId }),
        detail: result.requiresApproval ? 'paused for approval' : summarize(result.result, result.error),
      });
    },
  };
}

export default [incidentTimeline()];

/**
 * The incident-response kit, exercised offline: the directory is loaded in
 * place with `loadAgentDir()` / `resolveAgentDir()` (the kit's files import
 * `@lousho/build-ai-agent` by name, resolved to this repo's dist through the
 * workspace self-link - like kit.test.ts in examples/coding-harness, this
 * needs `npm run build` to have run).
 *
 * The scripted mockModel plays the responder: an alert arrives (the same
 * JSON the `alerts` webhook channel would deliver), the agent diagnoses with
 * read-only tools, and its remediation goes through the risk-tiered gate -
 * staging auto-allowed, production asks (the kit's approver annotates the
 * tier), destructive calls denied - while the audit hook writes the
 * timeline.
 */
import { beforeEach, describe, expect, it } from 'vitest';
import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { createAgent, loadAgentDir, resolveAgentDir } from '@lousho/build-ai-agent';
import { mockModel, type MockModel } from '@lousho/build-ai-agent/testing';
// static imports share the module instances the loader's dynamic import gets
import { infra, resetInfra } from './tools/infra.js';
import { resetTimeline, timeline } from './hooks.js';
import approve from './approve.js';

const DIR = __dirname; // the kit directory itself

const ALERT = JSON.stringify({
  alert: {
    id: 'PD-4821',
    service: 'payments-api',
    environment: 'production',
    severity: 'critical',
    summary: 'error_rate 14% (baseline 0.4%)',
  },
});

let timelineFile: string;
let tmpRoot: string;

beforeEach(() => {
  tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'incident-response-'));
  timelineFile = path.join(tmpRoot, 'timeline.jsonl');
  process.env.INCIDENT_TIMELINE_FILE = timelineFile;
  // set before any resolveAgentDir call so the channel file binds the HMAC secret at load
  process.env.INCIDENT_WEBHOOK_SECRET = 'test-secret';
  resetInfra();
  resetTimeline();
});

/** The tool-result messages of the provider's most recent request, joined - what the model saw. */
const toolOutputs = (provider: MockModel): string =>
  provider.calls[provider.calls.length - 1].messages
    .filter((m) => m.role === 'tool')
    .map((m) => String(m.content))
    .join('\n');

const auditLog = (): { audit: string[]; onPermissionDecision: (entry: { toolName: string; decision: string; rule?: { reason?: string } }) => void } => {
  const audit: string[] = [];
  return {
    audit,
    onPermissionDecision: (entry) => audit.push(`${entry.toolName}: ${entry.decision}${entry.rule?.reason ? ` (${entry.rule.reason})` : ''}`),
  };
};

describe('the kit, loaded in place', () => {
  it('discovers every tool, the skill and the alerts channel', async () => {
    const { manifest, channels } = await resolveAgentDir(DIR, { provider: mockModel(['x']) });
    expect(manifest.tools).toEqual([
      'check_logs',
      'query_metrics',
      'get_runbook',
      'check_status',
      'restart_service',
      'scale_replicas',
      'post_update',
      'drop_table',
      'delete_data',
    ]);
    expect(manifest.skills).toEqual(['incident-runbook']);
    expect(manifest.channels).toEqual(['alerts']);
    expect(channels[0].name).toBe('alerts');
  });
});

describe('the alerts webhook channel', () => {
  /** A request whose signature is computed with `key` (omit for unsigned). */
  const signedRequest = (body: string, key?: string) => {
    const rawBody = new TextEncoder().encode(body);
    const headers: Record<string, string> =
      key === undefined ? {} : { 'x-signature-256': `sha256=${crypto.createHmac('sha256', key).update(rawBody).digest('hex')}` };
    return { method: 'POST', url: '/channels/alerts', headers, rawBody, text: body };
  };

  it('requires the HMAC signature and turns an alert POST into agent input keyed on sessionKey', async () => {
    const { channels } = await resolveAgentDir(DIR, { provider: mockModel(['x']) });
    const channel = channels[0];
    const ok = async (req: ReturnType<typeof signedRequest>) => {
      const verdict = await channel.verify?.(req);
      return typeof verdict === 'object' ? verdict.ok : verdict !== false;
    };
    const body = JSON.stringify({ input: 'Alert: payments-api error_rate 14%', sessionKey: 'inc-4821' });

    expect(await ok(signedRequest(body))).toBe(false); // unsigned
    expect(await ok(signedRequest(body, 'bad'))).toBe(false); // wrong key
    expect(await ok(signedRequest(body, 'test-secret'))).toBe(true);

    const inbound = await channel.parse(signedRequest(body, 'test-secret'), () => {}, undefined as never);
    expect(inbound && 'input' in inbound && inbound.input).toBe('Alert: payments-api error_rate 14%');
    expect(inbound && 'sessionKey' in inbound && inbound.sessionKey).toBe('inc-4821');
  });
});

describe('an incident end to end', () => {
  it('diagnoses, gets the production restart approved at tier 2, verifies and audits every call', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'check_logs', args: { service: 'payments-api', severity: 'error' } }] },
      { toolCalls: [{ name: 'query_metrics', args: { service: 'payments-api', metric: 'error_rate' } }] },
      { toolCalls: [{ name: 'get_runbook', args: { topic: 'high-error-rate' } }] },
      { toolCalls: [{ name: 'restart_service', args: { service: 'payments-api', environment: 'production', reason: 'pool exhausted' } }] },
      { toolCalls: [{ name: 'check_status', args: { service: 'payments-api' } }] },
      { toolCalls: [{ name: 'post_update', args: { message: 'payments-api restarted; error_rate recovering', severity: 'info' } }] },
      { text: 'Mitigated: restarted payments-api in production (approved at tier 2); error_rate back to baseline.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    const result = await agent.send(ALERT);

    expect(result.finishReason).toBe('stop');
    expect(result.text).toContain('Mitigated');
    // diagnosis ran, the gate asked on the production restart, then it executed
    expect(audit).toContain('check_logs: allow');
    expect(audit).toContain('query_metrics: allow');
    expect(audit).toContain('restart_service: ask');
    expect(infra.services['payments-api'].status).toBe('healthy');
    expect(infra.services['payments-api'].restarts).toBe(2);
    // the update was posted and every call is on the timeline (memory + JSONL file)
    expect(infra.updates.map((u) => u.message)).toContain('payments-api restarted; error_rate recovering');
    // the approved call re-enters the pipeline after the pause, so its 'call' is recorded twice
    const calls = timeline.filter((e) => e.phase === 'call').map((e) => e.toolName);
    expect(calls).toEqual(['check_logs', 'query_metrics', 'get_runbook', 'restart_service', 'restart_service', 'check_status', 'post_update']);
    const restartResult = timeline.find((e) => e.toolName === 'restart_service' && e.phase === 'result');
    expect(restartResult?.detail).toContain('"after":"healthy"');
    const lines = fs.readFileSync(timelineFile, 'utf8').trim().split('\n').map((l) => JSON.parse(l) as { toolName: string; phase: string });
    expect(lines.filter((l) => l.toolName === 'restart_service').map((l) => l.phase)).toEqual(['call', 'approval', 'call', 'result']);
    // the model saw the canned diagnosis data
    expect(toolOutputs(provider)).toContain('pool exhausted');
  });

  it('pauses for a human when no approver answers, and resumes on approval', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'restart_service', args: { service: 'payments-api', environment: 'production' } }] },
      { toolCalls: [{ name: 'check_status', args: { service: 'payments-api' } }] },
      { text: 'Restarted after human approval; verified healthy.' },
    ]);
    const { config } = await resolveAgentDir(DIR, { provider });
    const agent = createAgent({ ...config, approve: undefined });

    const paused = await agent.send(ALERT);
    expect(paused.finishReason).toBe('awaiting-approval');
    const [pending] = await agent.approvals.list();
    expect(pending.toolName).toBe('restart_service');
    expect(infra.services['payments-api'].status).toBe('degraded'); // not executed while paused

    const result = await agent.approvals.resolve({ id: paused.approvalId!, approved: true });
    expect(result.finishReason).toBe('stop');
    expect(infra.services['payments-api'].status).toBe('healthy');
  });

  it('refuses tier-3 asks: scaling to zero is rejected by the kit approver', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'scale_replicas', args: { service: 'payments-api', environment: 'production', replicas: 0 } }] },
      { text: 'Approval refused - escalating to the on-call human.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    const result = await agent.send(ALERT);

    expect(result.finishReason).toBe('stop');
    expect(audit).toContain('scale_replicas: ask');
    expect(infra.services['payments-api'].desiredReplicas).toBe(3);
    expect(toolOutputs(provider)).toMatch(/reject|denied|refused/i);
  });

  it('auto-allows staging remediation without asking', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'restart_service', args: { service: 'checkout-web', environment: 'staging' } }] },
      { text: 'Staging restarted.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    await agent.send('Alert: checkout-web staging deploy check');

    expect(audit).toContain('restart_service: allow');
    expect(audit).not.toContain('restart_service: ask');
    expect(infra.services['checkout-web'].restarts).toBe(1);
  });
});

describe('the safety rails', () => {
  it('denies drop_table before the tool can run, leaving the data intact', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'drop_table', args: { table: 'payments' } }] },
      { text: 'The drop was denied by policy; escalating to the on-call human.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    await agent.send(ALERT);

    expect(audit).toContain("drop_table: deny (Destructive data operations are never within an incident responder's mandate)");
    expect(infra.databases.payments.rows).toBe(184_203);
    expect(toolOutputs(provider)).toContain('denied');
    expect(timeline.find((e) => e.toolName === 'drop_table')?.phase).toBe('call'); // the attempt is audited
  });

  it('denies delete_data too', async () => {
    const provider = mockModel([
      { toolCalls: [{ name: 'delete_data', args: { table: 'sessions' } }] },
      { text: 'Denied.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    await agent.send(ALERT);

    expect(audit).toContain("delete_data: deny (Destructive data operations are never within an incident responder's mandate)");
    expect(infra.databases.sessions.rows).toBe(51_977);
  });

  it('catches a model that labels a production service as staging to dodge the ask tier', async () => {
    const provider = mockModel([
      // the "allow staging" rule matches the claimed argument, but the tool
      // cross-checks the estate and refuses the mismatched call
      { toolCalls: [{ name: 'restart_service', args: { service: 'payments-api', environment: 'staging' } }] },
      { text: 'Environment mismatch caught - re-issuing as production with approval.' },
    ]);
    const { audit, onPermissionDecision } = auditLog();
    const agent = await loadAgentDir(DIR, { provider, onPermissionDecision });

    await agent.send(ALERT);

    expect(audit).toContain('restart_service: allow'); // the rule trusted the claimed arg
    expect(toolOutputs(provider)).toContain('environment mismatch'); // the tool did not
    expect(infra.services['payments-api'].status).toBe('degraded');
  });
});

describe('the kit approver', () => {
  const pending = (toolName: string, args: Record<string, unknown>) => ({ id: 'ap-1', toolCallId: 'call_1', toolName, args, createdAt: new Date().toISOString() });

  it('annotates tier-2 approvals and refuses everything hotter', () => {
    expect(approve(pending('restart_service', { environment: 'production' }))).toContain('risk tier 2');
    expect(approve(pending('scale_replicas', { environment: 'production', replicas: 4 }))).toContain('risk tier 2');
    expect(approve(pending('scale_replicas', { environment: 'production', replicas: 0 }))).toBe(false);
    expect(approve(pending('unknown_tool', {}))).toBe(false);
  });
});

/**
 * The kit's simulated infrastructure: a canned production/staging estate plus
 * the tools the responder calls against it. Everything runs offline - `infra`
 * is an in-memory fixture the tools read and mutate, so a restart or a scale
 * is visible to later calls (a test reloads this module and calls
 * `resetInfra()`).
 *
 * The remediation tools take an `environment` argument AND cross-check it
 * against the service's real environment: a permission rule that allows
 * "staging" trusts the argument the model wrote, so the tool refuses a call
 * that labels a production service as staging.
 */
import { z } from 'zod';
import { defineTool } from '@lousho/build-ai-agent';

export type Environment = 'staging' | 'production';
export type ServiceStatus = 'healthy' | 'degraded' | 'down' | 'restarting';

export interface ServiceState {
  name: string;
  environment: Environment;
  status: ServiceStatus;
  replicas: number;
  desiredReplicas: number;
  version: string;
  restarts: number;
}

export interface UpdateEntry {
  at: string;
  severity: 'info' | 'warning' | 'critical';
  message: string;
}

export interface InfraState {
  services: Record<string, ServiceState>;
  /** table -> rows still present; drop_table / delete_data eat into this. */
  databases: Record<string, { rows: number }>;
  /** Status-page updates the agent posted. */
  updates: UpdateEntry[];
  logs: Record<string, string[]>;
  runbooks: Record<string, { title: string; steps: string[] }>;
}

const seed = (): InfraState => ({
  services: {
    'payments-api': {
      name: 'payments-api',
      environment: 'production',
      status: 'degraded',
      replicas: 3,
      desiredReplicas: 3,
      version: 'v2.14.0',
      restarts: 1,
    },
    'checkout-web': {
      name: 'checkout-web',
      environment: 'staging',
      status: 'healthy',
      replicas: 2,
      desiredReplicas: 2,
      version: 'v1.9.3',
      restarts: 0,
    },
    'orders-db': {
      name: 'orders-db',
      environment: 'production',
      status: 'healthy',
      replicas: 1,
      desiredReplicas: 1,
      version: 'postgres-16.2',
      restarts: 0,
    },
  },
  databases: {
    payments: { rows: 184_203 },
    sessions: { rows: 51_977 },
  },
  updates: [],
  logs: {
    'payments-api': [
      '2024-05-11T14:02:11Z ERROR pool: connection timeout after 5000ms (pool exhausted, 32/32 in use)',
      '2024-05-11T14:02:14Z ERROR handler POST /charges failed: upstream timeout (payments-db)',
      '2024-05-11T14:02:31Z WARN  heap: 87% of limit, GC pause 1.2s',
      '2024-05-11T14:03:02Z ERROR pool: connection timeout after 5000ms (pool exhausted, 32/32 in use)',
      '2024-05-11T14:03:19Z ERROR handler POST /charges failed: upstream timeout (payments-db)',
    ],
    'checkout-web': [
      '2024-05-11T13:58:40Z INFO  GET /cart 200 in 41ms',
      '2024-05-11T14:01:55Z INFO  GET /checkout 200 in 63ms',
    ],
    'orders-db': [
      '2024-05-11T14:00:00Z INFO  checkpoint completed, wrote 812 buffers',
      '2024-05-11T14:05:00Z INFO  automatic vacuum of "orders": index scans 0',
    ],
  },
  runbooks: {
    'high-error-rate': {
      title: 'Elevated error rate on a service',
      steps: [
        'Correlate check_logs and query_metrics(error_rate, latency_p99) to find the failing dependency.',
        'If logs show an exhausted resource (pool, heap), a rolling restart clears the leak - this is tier 2 in production.',
        'If errors track a traffic spike, scale replicas instead - check the spike is real, not a retry storm.',
        'Verify error_rate returns to baseline with query_metrics before calling the incident mitigated.',
      ],
    },
    restart: {
      title: 'Rolling restart of a service',
      steps: [
        'restart_service performs a rolling restart; replicas stay up one short during the roll.',
        'Staging restarts are pre-approved. Production restarts need approval - state the blast radius in the request.',
        'After the restart, check_status must report healthy and query_metrics(error_rate) must fall before you post "mitigated".',
      ],
    },
    scale: {
      title: 'Scaling a service',
      steps: [
        'scale_replicas changes desiredReplicas; the platform converges within ~60s.',
        'Never scale to 0 during an incident - that is an outage, not a remediation. The approver refuses it.',
        'Verify with check_status that replicas converged.',
      ],
    },
  },
});

/** The live fixture the tools operate on. */
export const infra: InfraState = seed();

/** Back to the seeded state (tests). Mutates in place so importers keep their reference. */
export function resetInfra(): InfraState {
  const fresh = seed();
  infra.services = fresh.services;
  infra.databases = fresh.databases;
  infra.updates = fresh.updates;
  infra.logs = fresh.logs;
  infra.runbooks = fresh.runbooks;
  return infra;
}

const serviceArg = z.string().describe('The service name, e.g. "payments-api"');
const environmentArg = z.enum(['staging', 'production']).describe('The environment the caller believes the service runs in - verified against the estate.');

/** The service entry, or a model-facing error string. */
function service(name: string): ServiceState | { error: string } {
  const entry = infra.services[name];
  return entry ?? { error: `unknown service '${name}'. Known services: ${Object.keys(infra.services).join(', ')}` };
}

/**
 * Guards the environment claim: a permission rule that allows "staging" sees
 * only the argument, so the tool itself refuses when the claim disagrees with
 * the estate.
 */
function envGuard(entry: ServiceState, claimed: Environment): { error: string } | undefined {
  if (entry.environment !== claimed) {
    return {
      error: `environment mismatch: '${entry.name}' runs in ${entry.environment}, not ${claimed}. Re-issue the call with the real environment so it passes through the right approval tier.`,
    };
  }
  return undefined;
}

export const check_logs = defineTool({
  name: 'check_logs',
  description: 'Read the most recent log lines of a service (read-only)',
  input: z.object({
    service: serviceArg,
    severity: z.enum(['info', 'warn', 'error']).optional().describe('Only lines at or above this severity'),
    limit: z.number().int().min(1).max(50).optional().describe('Maximum lines to return (default 20)'),
  }),
  annotations: { readOnlyHint: true },
  execute({ service: name, severity, limit = 20 }) {
    const entry = service(name);
    if ('error' in entry) return entry;
    const floor = severity === 'error' ? 'ERROR' : severity === 'warn' ? 'WARN' : '';
    const lines = (infra.logs[name] ?? []).filter((line) => floor === '' || line.includes(floor)).slice(-limit);
    return { service: name, environment: entry.environment, lines };
  },
});

/** A plausible metric series: baseline wiggle, with a spike while the service is degraded. */
function series(entry: ServiceState, metric: string): { t: string; v: number }[] {
  const baseline: Record<string, number> = { error_rate: 0.4, latency_p99: 120, cpu: 34, memory: 58, restarts: entry.restarts };
  const spiked: Record<string, number> = { error_rate: 14.2, latency_p99: 5100, cpu: 61, memory: 87, restarts: entry.restarts };
  const hot = entry.status === 'degraded' || entry.status === 'down';
  const now = Date.UTC(2024, 4, 11, 14, 0, 0);
  return [0, 1, 2, 3, 4].map((i) => {
    const base = baseline[metric] ?? 0;
    const value = hot && i >= 3 ? (spiked[metric] ?? base) : base + i * 0.05;
    return { t: new Date(now - (4 - i) * 60_000).toISOString(), v: Math.round(value * 100) / 100 };
  });
}

export const query_metrics = defineTool({
  name: 'query_metrics',
  description: 'Query a service metric over the last window (read-only): error_rate, latency_p99, cpu, memory or restarts',
  input: z.object({
    service: serviceArg,
    metric: z.enum(['error_rate', 'latency_p99', 'cpu', 'memory', 'restarts']),
    windowMinutes: z.number().int().min(1).max(120).optional().describe('Lookback window (default 5m)'),
  }),
  annotations: { readOnlyHint: true },
  execute({ service: name, metric, windowMinutes = 5 }) {
    const entry = service(name);
    if ('error' in entry) return entry;
    const points = series(entry, metric);
    const latest = points.at(-1)!.v;
    return {
      service: name,
      metric,
      windowMinutes,
      points,
      summary: { current: latest, baseline: points[0].v, elevated: latest > points[0].v * 1.5 },
    };
  },
});

export const get_runbook = defineTool({
  name: 'get_runbook',
  description: 'Fetch the runbook procedure for a topic (read-only): "high-error-rate", "restart", "scale"',
  input: z.object({ topic: z.string().describe('Runbook topic, e.g. "high-error-rate"') }),
  annotations: { readOnlyHint: true },
  execute({ topic }) {
    const runbook = infra.runbooks[topic];
    if (!runbook) return { error: `no runbook for '${topic}'. Available: ${Object.keys(infra.runbooks).join(', ')}` };
    return { topic, ...runbook };
  },
});

export const check_status = defineTool({
  name: 'check_status',
  description: 'Current status of a service: health, replica count vs desired, version, restart count (read-only)',
  input: z.object({ service: serviceArg }),
  annotations: { readOnlyHint: true },
  execute({ service: name }) {
    const entry = service(name);
    if ('error' in entry) return entry;
    return { ...entry, converged: entry.replicas === entry.desiredReplicas };
  },
});

export const restart_service = defineTool({
  name: 'restart_service',
  description: 'Perform a rolling restart of a service. Staging restarts are pre-approved; production restarts need human approval.',
  input: z.object({
    service: serviceArg,
    environment: environmentArg,
    reason: z.string().optional().describe('Why the restart is needed - recorded on the incident timeline'),
  }),
  execute({ service: name, environment, reason }) {
    const entry = service(name);
    if ('error' in entry) return entry;
    const mismatch = envGuard(entry, environment);
    if (mismatch) return mismatch;
    const before = entry.status;
    entry.status = 'healthy';
    entry.restarts += 1;
    return {
      service: name,
      environment: entry.environment,
      before,
      after: entry.status,
      restarts: entry.restarts,
      ...(reason !== undefined && { reason }),
    };
  },
});

export const scale_replicas = defineTool({
  name: 'scale_replicas',
  description: 'Set the desired replica count of a service (1-20). Scaling to 0 during an incident is refused by policy.',
  input: z.object({
    service: serviceArg,
    environment: environmentArg,
    replicas: z.number().int().min(0).max(20).describe('Desired replica count'),
  }),
  execute({ service: name, environment, replicas }) {
    const entry = service(name);
    if ('error' in entry) return entry;
    const mismatch = envGuard(entry, environment);
    if (mismatch) return mismatch;
    const before = entry.desiredReplicas;
    entry.desiredReplicas = replicas;
    entry.replicas = replicas;
    return { service: name, environment: entry.environment, before, replicas: entry.replicas };
  },
});

export const post_update = defineTool({
  name: 'post_update',
  description: 'Post a status-page update for the incident (visible to stakeholders)',
  input: z.object({
    message: z.string().describe('The update text, e.g. "payments-api restarted; error rate recovering"'),
    severity: z.enum(['info', 'warning', 'critical']).optional(),
  }),
  execute({ message, severity = 'info' }) {
    const update: UpdateEntry = { at: new Date().toISOString(), severity, message };
    infra.updates.push(update);
    return { posted: true, update };
  },
});

/**
 * The destructive capabilities the estate exposes - present so the permission
 * rules have something real to fence. Both are denied by agent.json; if that
 * gate ever regressed these would actually destroy fixture state.
 */
export const drop_table = defineTool({
  name: 'drop_table',
  description: 'Drop a database table and all its rows. DESTRUCTIVE - never within the incident mandate.',
  input: z.object({ table: z.string().describe('Table name, e.g. "payments"') }),
  execute({ table }) {
    const target = infra.databases[table];
    if (!target) return { error: `unknown table '${table}'. Known tables: ${Object.keys(infra.databases).join(', ')}` };
    const rows = target.rows;
    delete infra.databases[table];
    return { dropped: table, rowsLost: rows };
  },
});

export const delete_data = defineTool({
  name: 'delete_data',
  description: 'Delete rows from a database table. DESTRUCTIVE - never within the incident mandate.',
  input: z.object({
    table: z.string(),
    where: z.string().optional().describe('Row predicate; without it every row goes'),
  }),
  execute({ table, where }) {
    const target = infra.databases[table];
    if (!target) return { error: `unknown table '${table}'. Known tables: ${Object.keys(infra.databases).join(', ')}` };
    const deleted = where === undefined ? target.rows : Math.floor(target.rows / 10);
    target.rows -= deleted;
    return { table, rowsDeleted: deleted, rowsRemaining: target.rows };
  },
});

